Object.assign(SNIP,{});PRESET_NOTES["l38"]={"Ví dụ: Gộp và tìm cơ bản": "Sau 4 lần gộp còn 4 tập: {0,1,2,3}, {4}, {5,6}, {7}. Ô có p[u] = u là gốc. 0 và 2 cùng gốc 3 nên in cung; 0 và 5 khác gốc nên in khac.", "Ví dụ: Nén đường đi": "Một lần find(0) đi hết dây, nhưng khi các lời gọi trả về, mọi nút trên đường đều được gán p = 5. Mảng thành 5 5 5 5 5 5: lần sau find bất kỳ nút nào cũng chỉ một bước.", "Ví dụ: Gộp theo kích cỡ": "unite(1, 3) trả về 0 (false) vì 1 và 3 đã cùng tập. unite(6, 0) gộp tập 3 phần tử {4,5,6} vào tập 4 phần tử {0,1,2,3}: gốc 0 giữ nguyên, kích cỡ thành 7.", "Ví dụ: Đếm thành phần liên thông": "Mỗi cạnh nối hai tập khác nhau làm số tập giảm 1. Cạnh cuối (2, 0) nối hai đỉnh đã cùng tập nên không đổi: đó là cạnh tạo chu trình. Kết quả 6 5 4 3 3.", "Lỗi: gắn đỉnh thay vì gắn gốc": "Lẽ ra 0, 1, 2 cùng một tập, nhưng unite(0, 2) ghi đè p[0] = 2 và cắt mất liên kết 0 → 1. find(1) = 1, find(2) = 2 nên in khac. Luôn gắn gốc vào gốc."};EX_HINTS["l38"]=[["find: nếu p[u] ≠ u thì p[u] = find(p[u]); trả về p[u].", "unite: lấy hai gốc a, b; trùng thì thôi; nếu sz[a] < sz[b] thì đổi chỗ; rồi p[b] = a, sz[a] += sz[b].", "Thiếu cả hai cải tiến, cây có thể thành một dây dài và mỗi câu hỏi tốn O(n)."], ["Ban đầu có n cụm. Mỗi sợi dây nối hai gốc khác nhau làm số cụm giảm đúng 1; nối hai máy đã cùng cụm thì không đổi.", "Dây u = u hay dây trùng: find cho cùng gốc, tự động không đếm.", "Đếm lại số cụm bằng BFS/DFS sau mỗi dây tốn O(n·m)."], ["sz[gốc] là số phần tử của cụm. Chỉ gốc mới giữ kích cỡ đúng.", "Cụm chỉ lớn lên, không bao giờ nhỏ đi: cụm lớn nhất chỉ có thể là cụm vừa được gộp. So lonNhat với sz của gốc mới.", "Không cần duyệt lại mọi cụm sau mỗi dây."]];
/* ===================== BÀI 38 · Hợp nhất tập hợp (DSU) ===================== */
/* Bài 38 · Hợp nhất tập hợp (DSU)
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR38=[{label:"Ví dụ: Gộp và tìm cơ bản",input:"",code:"#include <iostream>\nusing namespace std;\n\nint p[8];\n\nint find(int u) {\n    while (p[u] != u) u = p[u];        // đi lên tới gốc\n    return u;\n}\n\nvoid unite(int u, int v) {\n    int a = find(u), b = find(v);\n    if (a != b) p[a] = b;              // gắn gốc vào gốc\n}\n\nint main() {\n    for (int i = 0; i < 8; i++) p[i] = i;\n    unite(0, 1);\n    unite(2, 3);\n    unite(1, 3);\n    unite(5, 6);\n    cout << (find(0) == find(2) ? \"cung\" : \"khac\") << \" \";\n    cout << (find(0) == find(5) ? \"cung\" : \"khac\") << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"p",ptr:["u","a","b"]}],py:{code:"p = list(range(8))\n\ndef find(u):\n    while p[u] != u:           # đi lên tới gốc\n        u = p[u]\n    return u\n\ndef unite(u, v):\n    a, b = find(u), find(v)\n    if a != b:\n        p[a] = b               # gắn gốc vào gốc\n\nunite(0, 1)\nunite(2, 3)\nunite(1, 3)\nunite(5, 6)\nprint(\"cung\" if find(0) == find(2) else \"khac\", \"cung\" if find(0) == find(5) else \"khac\")"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] p = new int[8];\n\n    static int Find(int u)\n    {\n        while (p[u] != u) u = p[u];        // đi lên tới gốc\n        return u;\n    }\n\n    static void Unite(int u, int v)\n    {\n        int a = Find(u), b = Find(v);\n        if (a != b) p[a] = b;              // gắn gốc vào gốc\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < 8; i++) p[i] = i;\n        Unite(0, 1);\n        Unite(2, 3);\n        Unite(1, 3);\n        Unite(5, 6);\n        Console.WriteLine((Find(0) == Find(2) ? \"cung\" : \"khac\") + \" \" + (Find(0) == Find(5) ? \"cung\" : \"khac\"));\n    }\n}"}},{label:"Ví dụ: Nén đường đi",input:"",code:"#include <iostream>\nusing namespace std;\n\nint p[6] = {1, 2, 3, 4, 5, 5};        // một dây dài: 0 → 1 → 2 → 3 → 4 → 5\n\nint find(int u) {\n    if (p[u] != u) p[u] = find(p[u]);  // trỏ thẳng vào gốc\n    return p[u];\n}\n\nint main() {\n    cout << find(0) << \"\\n\";\n    for (int i = 0; i < 6; i++) cout << p[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"p",ptr:["u"]},{type:"calls"}],py:{code:"p = [1, 2, 3, 4, 5, 5]          # một dây dài: 0 → 1 → 2 → 3 → 4 → 5\n\ndef find(u):\n    if p[u] != u:\n        p[u] = find(p[u])      # trỏ thẳng vào gốc\n    return p[u]\n\nprint(find(0))\nprint(*p)"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] p = { 1, 2, 3, 4, 5, 5 };   // một dây dài: 0 → 1 → 2 → 3 → 4 → 5\n\n    static int Find(int u)\n    {\n        if (p[u] != u) p[u] = Find(p[u]);  // trỏ thẳng vào gốc\n        return p[u];\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(Find(0));\n        Console.WriteLine(string.Join(\" \", p));\n    }\n}"}},{label:"Ví dụ: Gộp theo kích cỡ",input:"",code:"#include <iostream>\nusing namespace std;\n\nint p[8], sz[8];\n\nint find(int u) {\n    if (p[u] != u) p[u] = find(p[u]);\n    return p[u];\n}\n\nbool unite(int u, int v) {\n    int a = find(u), b = find(v);\n    if (a == b) return false;          // đã cùng tập\n    if (sz[a] < sz[b]) swap(a, b);     // a là gốc của tập lớn hơn\n    p[b] = a;\n    sz[a] += sz[b];\n    return true;\n}\n\nint main() {\n    for (int i = 0; i < 8; i++) { p[i] = i; sz[i] = 1; }\n    unite(0, 1); unite(2, 3); unite(0, 2);\n    unite(4, 5); unite(4, 6);\n    cout << unite(1, 3) << \" \" << unite(6, 0) << \"\\n\";\n    cout << sz[find(3)] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"p",ptr:["a","b"]},{type:"cells",of:"sz",ptr:["a","b"]}],py:{code:"p = list(range(8))\nsz = [1] * 8\n\ndef find(u):\n    if p[u] != u:\n        p[u] = find(p[u])\n    return p[u]\n\ndef unite(u, v):\n    a, b = find(u), find(v)\n    if a == b:\n        return False           # đã cùng tập\n    if sz[a] < sz[b]:\n        a, b = b, a            # a là gốc của tập lớn hơn\n    p[b] = a\n    sz[a] += sz[b]\n    return True\n\nunite(0, 1); unite(2, 3); unite(0, 2)\nunite(4, 5); unite(4, 6)\nprint(unite(1, 3), unite(6, 0))\nprint(sz[find(3)])",note:"unite(1, 3) trả về False vì 1 và 3 đã cùng tập. unite(6, 0) gộp tập 3 phần tử {4,5,6} vào tập 4 phần tử {0,1,2,3}: gốc 0 giữ nguyên, kích cỡ thành 7."},cs:{code:"using System;\n\nclass Program\n{\n    static int[] p = new int[8], sz = new int[8];\n\n    static int Find(int u)\n    {\n        if (p[u] != u) p[u] = Find(p[u]);\n        return p[u];\n    }\n\n    static bool Unite(int u, int v)\n    {\n        int a = Find(u), b = Find(v);\n        if (a == b) return false;          // đã cùng tập\n        if (sz[a] < sz[b]) (a, b) = (b, a);   // a là gốc của tập lớn hơn\n        p[b] = a;\n        sz[a] += sz[b];\n        return true;\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < 8; i++) { p[i] = i; sz[i] = 1; }\n        Unite(0, 1); Unite(2, 3); Unite(0, 2);\n        Unite(4, 5); Unite(4, 6);\n        Console.WriteLine(Unite(1, 3) + \" \" + Unite(6, 0));\n        Console.WriteLine(sz[Find(3)]);\n    }\n}",note:"Unite(1, 3) trả về False vì 1 và 3 đã cùng tập. Unite(6, 0) gộp tập 3 phần tử {4,5,6} vào tập 4 phần tử {0,1,2,3}: gốc 0 giữ nguyên, kích cỡ thành 7."}},{label:"Ví dụ: Đếm thành phần liên thông",input:"",code:"#include <iostream>\nusing namespace std;\n\nint p[7];\n\nint find(int u) {\n    if (p[u] != u) p[u] = find(p[u]);\n    return p[u];\n}\n\nint main() {\n    int n = 7, soTap = 7;\n    int eu[5] = {0, 1, 3, 4, 2};\n    int ev[5] = {1, 2, 4, 5, 0};\n    for (int i = 0; i < n; i++) p[i] = i;\n    for (int i = 0; i < 5; i++) {\n        int a = find(eu[i]), b = find(ev[i]);\n        if (a != b) {\n            p[a] = b;\n            soTap--;                   // mỗi lần gộp thật sự bớt một tập\n        }\n        cout << soTap << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"p",ptr:["a","b"]}],py:{code:"n = 7\np = list(range(n))\n\ndef find(u):\n    if p[u] != u:\n        p[u] = find(p[u])\n    return p[u]\n\ncanh = [(0, 1), (1, 2), (3, 4), (4, 5), (2, 0)]\nso_tap = n\nout = []\nfor u, v in canh:\n    a, b = find(u), find(v)\n    if a != b:\n        p[a] = b\n        so_tap -= 1            # mỗi lần gộp thật sự bớt một tập\n    out.append(so_tap)\nprint(*out)"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] p = new int[7];\n\n    static int Find(int u)\n    {\n        if (p[u] != u) p[u] = Find(p[u]);\n        return p[u];\n    }\n\n    static void Main()\n    {\n        int n = 7, soTap = 7;\n        int[] eu = { 0, 1, 3, 4, 2 };\n        int[] ev = { 1, 2, 4, 5, 0 };\n        for (int i = 0; i < n; i++) p[i] = i;\n        for (int i = 0; i < 5; i++)\n        {\n            int a = Find(eu[i]), b = Find(ev[i]);\n            if (a != b)\n            {\n                p[a] = b;\n                soTap--;                       // mỗi lần gộp thật sự bớt một tập\n            }\n            Console.Write(soTap + \" \");\n        }\n        Console.WriteLine();\n    }\n}"}},{label:"Lỗi: gắn đỉnh thay vì gắn gốc",input:"",code:"#include <iostream>\nusing namespace std;\n\nint p[4];\n\nint find(int u) {\n    while (p[u] != u) u = p[u];\n    return u;\n}\n\nvoid unite(int u, int v) {\n    p[u] = v;                          // SAI: phải là p[find(u)] = find(v)\n}\n\nint main() {\n    for (int i = 0; i < 4; i++) p[i] = i;\n    unite(0, 1);\n    unite(0, 2);                       // ghi đè p[0]: 0 rời khỏi 1\n    cout << (find(1) == find(2) ? \"cung\" : \"khac\") << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"p",ptr:["u","v"]}],py:{code:"p = list(range(4))\n\ndef find(u):\n    while p[u] != u:\n        u = p[u]\n    return u\n\ndef unite(u, v):\n    p[u] = v                   # SAI: phải là p[find(u)] = find(v)\n\nunite(0, 1)\nunite(0, 2)                    # ghi đè p[0]: 0 rời khỏi 1\nprint(\"cung\" if find(1) == find(2) else \"khac\")"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] p = new int[4];\n\n    static int Find(int u)\n    {\n        while (p[u] != u) u = p[u];\n        return u;\n    }\n\n    static void Unite(int u, int v)\n    {\n        p[u] = v;                          // SAI: phải là p[Find(u)] = Find(v)\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < 4; i++) p[i] = i;\n        Unite(0, 1);\n        Unite(0, 2);                           // ghi đè p[0]: 0 rời khỏi 1\n        Console.WriteLine(Find(1) == Find(2) ? \"cung\" : \"khac\");\n    }\n}"}}];
