makeEx2(document.getElementById("ex-l38"),sim38,[{t:"Mạng máy tính",d:"Có n máy (đánh số 1 … n), ban đầu chưa nối với nhau. Đầu vào: dòng đầu n và q (1 ≤ n, q ≤ 2·10^5); q dòng sau, mỗi dòng “t u v”: t = 1 là nối dây giữa máy u và v; t = 2 là câu hỏi u và v đã thông nhau chưa (trực tiếp hay qua máy khác). Đầu ra: với mỗi câu hỏi in YES hoặc NO trên một dòng.",tests:[{in:"4 6\n1 1 2\n2 1 2\n2 1 3\n1 2 3\n2 1 3\n2 4 4",out:"YES\nNO\nYES\nYES"},{in:"1 1\n2 1 1",out:"YES"},{in:"5 6\n1 1 2\n1 3 4\n2 2 4\n1 2 3\n2 1 4\n2 5 1",out:"NO\nYES\nNO"},{in:"3 5\n1 1 1\n2 1 2\n1 3 2\n1 2 3\n2 3 2",out:"NO\nYES"},{in:"30 80\n2 14 14\n2 4 3\n1 23 15\n1 2 20\n2 6 19\n1 11 9\n2 11 20\n2 10 16\n2 13 8\n2 3 17\n1 5 14\n2 8 1\n1 12 24\n2 30 22\n2 17 1\n1 16 4\n1 4 24\n1 29 15\n1 4 25\n1 10 22\n1 12 15\n1 16 10\n2 9 6\n1 9 23\n2 6 23\n1 3 8\n2 24 19\n1 10 24\n1 5 28\n1 29 30\n1 26 12\n1 1 30\n2 17 27\n2 19 30\n1 28 29\n2 2 8\n1 5 22\n1 30 22\n1 6 20\n2 2 18\n1 26 1\n1 13 5\n2 28 25\n2 22 24\n2 9 7\n1 11 23\n1 21 24\n1 25 3\n1 23 18\n2 7 10\n1 5 14\n1 1 17\n1 23 8\n1 2 4\n2 18 30\n1 18 23\n1 20 13\n1 23 21\n1 25 14\n1 14 29\n2 16 15\n1 6 7\n1 19 23\n1 19 23\n1 20 9\n1 1 22\n2 25 30\n1 7 20\n1 3 6\n2 4 12\n1 14 15\n1 17 13\n1 21 8\n2 7 8\n2 12 9\n1 5 28\n2 19 29\n1 11 28\n1 22 29\n1 2 30",out:"YES\nNO\nNO\nNO\nNO\nNO\nNO\nNO\nNO\nNO\nNO\nNO\nNO\nNO\nNO\nNO\nNO\nYES\nYES\nNO\nNO\nYES\nYES\nYES\nYES\nYES\nYES\nYES"}],start:"#include <iostream>\nusing namespace std;\n\nint p[200005], sz[200005];\n\nint find(int u) {\n    return u;          // sửa: đi lên tới gốc, có nén đường đi\n}\n\nvoid unite(int u, int v) {\n    // gắn gốc của tập nhỏ vào gốc của tập lớn\n}\n\nint main() {\n    int n, q;\n    cin >> n >> q;\n    for (int i = 1; i <= n; i++) { p[i] = i; sz[i] = 1; }\n    for (int i = 0; i < q; i++) {\n        int t, u, v;\n        cin >> t >> u >> v;\n        if (t == 1) unite(u, v);\n        else cout << (find(u) == find(v) ? \"YES\" : \"NO\") << \"\\n\";\n    }\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=2;i<=n;i++)r.push("1 1 "+i);for(let i=0;i<n;i++)r.push("2 1 "+(1+(i*7)%n));return n+" "+r.length+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+200,why:"Không nén đường đi và không gộp theo kích cỡ, cây thành một dây dài n nút: mỗi find tốn O(n), cả bài O(n²)."},py:{start:"import sys\nsys.setrecursionlimit(10000)\n\nn, q = map(int, input().split())\np = list(range(n + 1))\nsz = [1] * (n + 1)\n\ndef find(u):\n    return u                   # sửa: đi lên tới gốc, có nén đường đi\n\ndef unite(u, v):\n    pass                       # gắn gốc của tập nhỏ vào gốc của tập lớn\n\nout = []\nfor _ in range(q):\n    t, u, v = map(int, input().split())\n    if t == 1:\n        unite(u, v)\n    else:\n        out.append(\"YES\" if find(u) == find(v) else \"NO\")\nprint(\"\\n\".join(out))",hints:["find: nếu p[u] != u thì p[u] = find(p[u]); trả về p[u].","unite: lấy hai gốc a, b; trùng thì thôi; nếu sz[a] < sz[b] thì đổi chỗ; rồi p[b] = a, sz[a] += sz[b].","Thiếu cả hai cải tiến, cây có thể thành một dây dài và mỗi câu hỏi tốn O(n)."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static int[] p, sz;\n\n    static int Find(int u)\n    {\n        return u;          // sửa: đi lên tới gốc, có nén đường đi\n    }\n\n    static void Unite(int u, int v)\n    {\n        // gắn gốc của tập nhỏ vào gốc của tập lớn\n    }\n\n    static void Main()\n    {\n        int[] nq = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nq[0];\n        p = new int[n + 1];\n        sz = new int[n + 1];\n        for (int i = 1; i <= n; i++) { p[i] = i; sz[i] = 1; }\n        var sb = new StringBuilder();\n        for (int i = 0; i < nq[1]; i++)\n        {\n            int[] t = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            if (t[0] == 1) Unite(t[1], t[2]);\n            else sb.Append(Find(t[1]) == Find(t[2]) ? \"YES\" : \"NO\").Append('\\n');\n        }\n        Console.Write(sb.ToString());\n    }\n}",hints:["Find: nếu p[u] != u thì p[u] = Find(p[u]); trả về p[u].","Unite: lấy hai gốc a, b; trùng thì thôi; nếu sz[a] < sz[b] thì đổi chỗ; rồi p[b] = a, sz[a] += sz[b].","Thiếu cả hai cải tiến, cây có thể thành một dây dài và mỗi câu hỏi tốn O(n)."]}},{t:"Đếm cụm sau mỗi dây",d:"Đầu vào: dòng đầu n và m (1 ≤ n, m ≤ 2·10^5); m dòng sau, mỗi dòng một sợi dây nối hai máy u v (1 ≤ u, v ≤ n, có thể u = v hoặc trùng dây cũ). Đầu ra: một dòng gồm m số, số thứ i là số cụm (thành phần liên thông) sau khi nối i sợi dây đầu tiên.",tests:[{in:"5 6\n1 2\n3 4\n2 1\n1 3\n5 5\n4 5",out:"4 3 3 2 2 1"},{in:"1 1\n1 1",out:"1"},{in:"3 3\n1 2\n2 3\n3 1",out:"2 1 1"},{in:"6 5\n1 6\n2 5\n3 4\n6 5\n4 1",out:"5 4 3 2 1"},{in:"40 60\n33 25\n21 17\n24 18\n28 8\n27 28\n29 38\n29 16\n12 38\n24 34\n9 30\n17 17\n18 15\n27 8\n5 23\n32 39\n20 18\n37 11\n34 20\n1 3\n1 16\n33 22\n17 8\n10 32\n3 19\n3 5\n35 27\n16 27\n4 12\n11 11\n24 27\n39 14\n8 11\n19 28\n4 33\n35 29\n33 3\n30 33\n17 10\n1 18\n32 1\n38 12\n40 34\n2 18\n17 34\n4 1\n21 6\n5 28\n25 10\n40 29\n8 19\n13 13\n37 12\n38 19\n33 16\n26 38\n6 2\n5 18\n22 25\n11 11\n19 35",out:"39 38 37 36 35 34 33 32 31 30 30 29 29 28 27 26 25 25 24 23 22 21 20 19 18 17 16 15 15 14 13 12 12 11 11 11 10 9 9 9 9 8 7 7 7 6 6 6 6 6 6 6 6 6 5 5 5 5 5 5"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<int> p, sz;\n\nint find(int u) {\n    return u;\n}\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    p.resize(n + 1);\n    sz.assign(n + 1, 1);\n    for (int i = 1; i <= n; i++) p[i] = i;\n    int soCum = n;\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        // gộp; nếu hai máy đang ở hai cụm khác nhau thì soCum giảm 1\n        cout << soCum << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=2;i<=n;i++)r.push("1 "+i);return n+" "+r.length+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+200,why:"Đếm lại từ đầu sau mỗi dây, hoặc DSU không có hai cải tiến (cây thành dây dài), đều tốn O(n²)."},py:{start:"n, m = map(int, input().split())\np = list(range(n + 1))\nsz = [1] * (n + 1)\n\ndef find(u):\n    return u\n\nso_cum = n\nout = []\nfor _ in range(m):\n    u, v = map(int, input().split())\n    # gộp; nếu hai máy đang ở hai cụm khác nhau thì so_cum giảm 1\n    out.append(so_cum)\nprint(*out)",hints:["Ban đầu có n cụm. Mỗi sợi dây nối hai gốc khác nhau làm số cụm giảm đúng 1; nối hai máy đã cùng cụm thì không đổi.","find không đệ quy: trong vòng lặp gán p[u] = p[p[u]] (trỏ lên ông) rồi đi lên; cũng làm cây thấp như nén đường đi.","Đếm lại số cụm bằng BFS/DFS sau mỗi dây tốn O(n·m)."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static int[] p, sz;\n\n    static int Find(int u)\n    {\n        return u;\n    }\n\n    static void Main()\n    {\n        int[] nq = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nq[0];\n        p = new int[n + 1];\n        sz = new int[n + 1];\n        for (int i = 1; i <= n; i++) { p[i] = i; sz[i] = 1; }\n        var sb = new StringBuilder();\n        int soCum = n;\n        for (int i = 0; i < nq[1]; i++)\n        {\n            int[] t = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            // gộp t[0] và t[1]; nếu đang ở hai cụm khác nhau thì soCum giảm 1\n            sb.Append(soCum).Append(' ');\n        }\n        Console.WriteLine(sb.ToString());\n    }\n}",hints:["Ban đầu có n cụm. Mỗi sợi dây nối hai gốc khác nhau làm số cụm giảm đúng 1; nối hai máy đã cùng cụm thì không đổi.","Dây u = u hay dây trùng: Find cho cùng gốc, tự động không đếm.","Đếm lại số cụm bằng BFS/DFS sau mỗi dây tốn O(n·m)."]}},{t:"Cụm lớn nhất",d:"Đầu vào giống bài trước: n, m và m sợi dây. Đầu ra: một dòng m số, số thứ i là số máy của cụm lớn nhất sau khi nối i sợi dây đầu tiên.",tests:[{in:"5 6\n1 2\n3 4\n2 1\n1 3\n5 5\n4 5",out:"2 2 2 4 4 5"},{in:"1 1\n1 1",out:"1"},{in:"6 5\n1 2\n3 4\n5 6\n2 3\n6 4",out:"2 2 2 4 6"},{in:"4 2\n4 4\n1 2",out:"1 2"},{in:"50 50\n17 20\n33 2\n22 18\n49 21\n50 16\n7 5\n2 22\n9 10\n4 21\n41 24\n2 9\n39 44\n10 44\n14 38\n49 9\n35 3\n26 33\n17 2\n1 36\n3 30\n17 28\n12 31\n50 3\n16 32\n19 29\n11 8\n28 25\n50 41\n10 11\n43 22\n2 40\n35 16\n3 3\n2 45\n48 1\n11 22\n40 16\n40 21\n29 31\n7 44\n32 49\n27 15\n43 27\n43 37\n40 50\n5 46\n6 16\n8 33\n15 49\n47 27",out:"2 2 2 2 2 2 4 4 4 4 6 6 8 8 11 11 12 14 14 14 15 15 15 15 15 15 16 16 18 19 20 20 20 21 21 21 29 29 29 31 31 31 33 34 34 35 36 36 36 37"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<int> p, sz;\n\nint find(int u) {\n    if (p[u] != u) p[u] = find(p[u]);\n    return p[u];\n}\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    p.resize(n + 1);\n    sz.assign(n + 1, 1);\n    for (int i = 1; i <= n; i++) p[i] = i;\n    int lonNhat = 1;\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        // gộp theo kích cỡ; kích cỡ cụm mới có thể vượt lonNhat\n        cout << lonNhat << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=2;i<=n;i++)r.push((i%2?1:2)+" "+i);return n+" "+r.length+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+200,why:"Tìm cụm lớn nhất bằng cách duyệt mọi gốc sau mỗi dây tốn O(n·m)."},py:{start:"n, m = map(int, input().split())\np = list(range(n + 1))\nsz = [1] * (n + 1)\n\ndef find(u):\n    while p[u] != u:\n        p[u] = p[p[u]]\n        u = p[u]\n    return u\n\nlon_nhat = 1\nout = []\nfor _ in range(m):\n    u, v = map(int, input().split())\n    # gộp theo kích cỡ; kích cỡ cụm mới có thể vượt lon_nhat\n    out.append(lon_nhat)\nprint(*out)",hints:["sz[gốc] là số phần tử của cụm. Chỉ gốc mới giữ kích cỡ đúng.","Cụm chỉ lớn lên, không bao giờ nhỏ đi: cụm lớn nhất chỉ có thể là cụm vừa được gộp. So lon_nhat với sz của gốc mới.","Không cần duyệt lại mọi cụm sau mỗi dây."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static int[] p, sz;\n\n    static int Find(int u)\n    {\n        if (p[u] != u) p[u] = Find(p[u]);\n        return p[u];\n    }\n\n    static void Main()\n    {\n        int[] nq = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nq[0];\n        p = new int[n + 1];\n        sz = new int[n + 1];\n        for (int i = 1; i <= n; i++) { p[i] = i; sz[i] = 1; }\n        var sb = new StringBuilder();\n        int lonNhat = 1;\n        for (int i = 0; i < nq[1]; i++)\n        {\n            int[] t = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            // gộp theo kích cỡ; kích cỡ cụm mới có thể vượt lonNhat\n            sb.Append(lonNhat).Append(' ');\n        }\n        Console.WriteLine(sb.ToString());\n    }\n}",hints:["sz[gốc] là số phần tử của cụm. Chỉ gốc mới giữ kích cỡ đúng.","Cụm chỉ lớn lên, không bao giờ nhỏ đi: cụm lớn nhất chỉ có thể là cụm vừa được gộp. So lonNhat với sz của gốc mới.","Không cần duyệt lại mọi cụm sau mỗi dây."]}}]);

makeQuiz("quiz38","score38",[{"q": "Trong DSU dùng mảng cha p, phần tử u là gốc khi?", "o": ["p[u] = 0", "p[u] = u", "p[u] = −1 luôn luôn", "u là số nhỏ nhất của tập"], "a": 1, "e": "Quy ước trong bài: gốc trỏ về chính nó. (Có cách cài khác dùng p[gốc] = −kích cỡ.)"}, {"q": "unite(u, v) đúng phải làm gì?", "o": ["p[u] = v", "p[find(u)] = find(v)", "p[v] = u", "sz[u] += sz[v]"], "a": 1, "e": "Gắn gốc vào gốc; gắn đỉnh u thì ghi đè cha cũ của u và làm vỡ tập."}, {"q": "Gộp theo kích cỡ gắn gốc nào vào gốc nào?", "o": ["Tập lớn vào tập nhỏ", "Tập nhỏ vào tập lớn", "Số nhỏ vào số lớn", "Ngẫu nhiên"], "a": 1, "e": "Mỗi lần một nút bị đẩy sâu thêm, tập chứa nó ít nhất gấp đôi: độ sâu ≤ log₂ n."}, {"q": "Bài toán nào KHÔNG làm trực tiếp được bằng DSU?", "o": ["Đếm số cụm khi thêm cạnh", "Kiểm tra hai đỉnh liên thông khi thêm cạnh", "Kiểm tra liên thông khi xóa cạnh", "Phát hiện cạnh tạo chu trình"], "a": 2, "e": "DSU chỉ gộp, không tách tập ra được."}]);

